using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;
public static class PolishCemetery{
 public static string Run(){
  string folder="Assets/Resources/ExpeditionEnemies/Cemetery/";
  foreach(var name in new[]{"Executioner","StrawReaper","Watcher"}){string path=folder+name+".prefab";var g=PrefabUtility.LoadPrefabContents(path);try{var a=g.GetComponentInChildren<Animator>();var c=(AnimatorController)a.runtimeAnimatorController;var machine=c.layers[0].stateMachine;foreach(var pair in new[]{new[]{"HeavyAttack","Melee"},new[]{"BlockIdle","Idle"}}){var src=machine.states.First(s=>s.state.name==pair[1]).state;var dst=machine.states.FirstOrDefault(s=>s.state.name==pair[0]).state??machine.AddState(pair[0]);dst.motion=src.motion;dst.speedParameter="ActionSpeed";dst.speedParameterActive=pair[0]=="HeavyAttack";}
   a.Rebind();a.Play("Idle",0,0);a.Update(0);var left=a.GetBoneTransform(HumanBodyBones.LeftFoot);var right=a.GetBoneTransform(HumanBodyBones.RightFoot);if(left&&right){float floor=Mathf.Min(left.position.y,right.position.y);a.transform.position+=Vector3.up*(.12f-floor);}
   PrefabUtility.SaveAsPrefabAsset(g,path);EditorUtility.SetDirty(c);
  }finally{PrefabUtility.UnloadPrefabContents(g);}}
  var metal=new Material(Shader.Find("Universal Render Pipeline/Lit"));metal.SetColor("_BaseColor",new Color(.07f,.08f,.075f));metal.SetFloat("_Metallic",.75f);metal.SetFloat("_Smoothness",.3f);string matpath="Assets/Resources/GothicArchitecture/CemeteryIron.mat";var saved=AssetDatabase.LoadAssetAtPath<Material>(matpath);if(!saved){AssetDatabase.CreateAsset(metal,matpath);saved=metal;}else UnityEngine.Object.DestroyImmediate(metal);
  string fp="Assets/Resources/GothicArchitecture/CemeteryFence.prefab";var fence=PrefabUtility.LoadPrefabContents(fp);foreach(var r in fence.GetComponentsInChildren<Renderer>())r.sharedMaterial=saved;foreach(float y in new[]{.5f,1.9f}){var rail=GameObject.CreatePrimitive(PrimitiveType.Cube);rail.name="Wrought iron rail";rail.transform.SetParent(fence.transform,false);rail.transform.localPosition=new Vector3(0,y,0);rail.transform.localScale=new Vector3(4,.07f,.09f);rail.GetComponent<Renderer>().sharedMaterial=saved;}PrefabUtility.SaveAsPrefabAsset(fence,fp);PrefabUtility.UnloadPrefabContents(fence);
  var earth=new Material(Resources.Load<Material>("CindersStone/Floor"));earth.SetColor("_BaseColor",new Color(.22f,.19f,.145f));string ep="Assets/Resources/GothicArchitecture/CemeteryEarth.mat";var em=AssetDatabase.LoadAssetAtPath<Material>(ep);if(!em){AssetDatabase.CreateAsset(earth,ep);em=earth;}else UnityEngine.Object.DestroyImmediate(earth);
  var ground=new GameObject("CemeteryGround");var tile=GameObject.CreatePrimitive(PrimitiveType.Cube);tile.transform.SetParent(ground.transform,false);tile.transform.localPosition=Vector3.up*.175f;tile.transform.localScale=new Vector3(4,.35f,4);tile.GetComponent<Renderer>().sharedMaterial=em;PrefabUtility.SaveAsPrefabAsset(ground,"Assets/Resources/GothicArchitecture/CemeteryGround.prefab");UnityEngine.Object.DestroyImmediate(ground);AssetDatabase.SaveAssets();return "Grounded humanoids, heavy states, iron fences, earth tiles";
 }
}
